<?php $cases=$a->db->all('SELECT * FROM cy_aftersales WHERE order_id=? ORDER BY id DESC LIMIT 10',[(int)$order['id']]);$active=false; ?>
<?php foreach($cases as $case): $active=$active||!in_array($case['state'],['completed','rejected','cancelled'],true); ?><div class="service-card"><div class="row between wrap"><strong><?= t('Service request') ?> #<?= (int)$case['id'] ?></strong><span class="pill"><?= t($case['state']) ?></span></div><p><?= t($case['kind']) ?> &middot; <?= e($case['reason']) ?></p><?php if($case['note']): ?><p class="commerce-note"><?= nl2br(e($case['note'])) ?></p><?php endif ?><?php foreach(['return_tracking','replacement_tracking'] as $track): if($case[$track]): ?><p><?= t($track) ?>: <?= e($a->crypto->open($case[$track])) ?></p><?php endif;endforeach ?>
<?php if($case['state']==='awaiting_return'): ?><?= form_start('aftersale_customer','','',false).hidden('id',$case['id']).hidden('revision',$case['revision']).hidden('operation','return') ?><?php field('tracking','Return carrier and tracking number','','text',['required'=>'required','maxlength'=>'1000']);button('Submit return shipment','secondary small','box'); ?></form><?php endif ?>
<?php if(in_array($case['state'],['requested','awaiting_return','replacement_shipped'],true)): ?><?= form_start('aftersale_customer','','',false).hidden('id',$case['id']).hidden('revision',$case['revision']).hidden('operation',$case['state']==='replacement_shipped'?'received':'cancel') ?><?php button($case['state']==='replacement_shipped'?'Confirm replacement receipt':'Cancel service request','ghost small','check'); ?></form><?php endif ?></div><?php endforeach ?>
<?php if(!$active&&$order['status']==='paid'): ?><details class="commerce-details"><summary><?= t('Request after-sales support') ?></summary><?= form_start('aftersale_request','','',false).hidden('order_id',$order['id']) ?><?php $m=json_decode($order['metadata'],true,32,JSON_THROW_ON_ERROR);$shipped=($m['product_type']??'')==='physical'&&in_array($order['fulfillment'],['shipped','received'],true);$options=$shipped?['return_refund'=>'Return and refund','exchange'=>'Exchange the same product']:['refund'=>'Refund'];select_field('kind','Service type',$options,array_key_first($options));field('reason','Reason','','textarea',['required'=>'required','maxlength'=>'2000']);button('Submit request','secondary','message'); ?></form><p class="hint"><?= t('Refunds require merchant approval. Confirmed direct payments return through the original provider, not as newly created wallet credit.') ?></p></details><?php endif ?>